import json
with open('/app/resources/treasury_bulletin_1939_10.json') as f:
    data = json.load(f)
elements = data.get('document', {}).get('elements', [])
# Look for table types
for i, el in enumerate(elements):
    if el.get('type') == 'table':
        print(f'Element {i}: table')
        # Print some details about the table
        if 'rows' in el:
            print(f'  Has {len(el.get(\"rows\", []))} rows')
        if 'headers' in el:
            print(f'  Has headers')
    # Look for text containing 'receipts'
    if el.get('type') == 'text':
        text = el.get('text', '')
        if 'receipts' in text.lower() and 'october' in text.lower():
            print(f'Element {i} (text): {text[:200]}')"
